function App(){const[p,setP]=useState<Profile>(empty),[hydrated,setHydrated]=useState(false),[page,setPage]=useState('home'),[busy,setBusy]=useState(false),[progress,setProgress]=useState(''),[error,setError]=useState(''),[docRole,setDocRole]=useState<'material'|'template'|'answers'>('material'),[selected,setSelected]=useState<string[]>([]),[mode,setMode]=useState('normal'),[level,setLevel]=useState('medium'),[count,setCount]=useState(5),[mins,setMins]=useState(45),[current,setCurrent]=useState<string|null>(null),[activeQ,setActiveQ]=useState(0),[tick,setTick]=useState(0),[practiceTopic,setPracticeTopic]=useState(''),[correctionDocId,setCorrectionDocId]=useState(''),[correctionTargetId,setCorrectionTargetId]=useState(''),[showMenu,setShowMenu]=useState(false),[aiConsent,setAiConsent]=useState(false),[aiRequest,setAiRequest]=useState<'questions'|'grade'|null>(null),[aiPreview,setAiPreview]=useState(''),[aiBusy,setAiBusy]=useState(false),[aiQuestions,setAiQuestions]=useState<Q[]>([]);const profileRef=useRef<Profile>(empty);const fileRef=useRef<HTMLInputElement>(null);const answerRef=useRef<HTMLInputElement>(null);const templateRef=useRef<HTMLInputElement>(null);const t=words[p.lang]||words.de;const exam=p.exams.find(e=>e.id===current);useEffect(()=>{get('profile').then(v=>{const fallback=localStorage.getItem('examvision-profile');const saved=v||(fallback?JSON.parse(fallback):undefined);if(saved)setP(saved as Profile)}).catch(e=>setError(`Local storage read failed: ${e instanceof Error?e.message:e}`)).finally(()=>setHydrated(true))},[]);useEffect(()=>{profileRef.current=p;if(hydrated){try{localStorage.setItem('examvision-profile',JSON.stringify(p))}catch(e){setError(`Browser storage unavailable: ${e instanceof Error?e.message:e}`)}set('profile',p).catch(e=>setError(`Local storage write failed: ${e instanceof Error?e.message:e}`))}},[p,hydrated]);useEffect(()=>{if(exam&&!exam.submitted&&exam.mode==='exam'){const i=window.setInterval(()=>setTick(x=>{if(x+1>=exam.duration*60){window.setTimeout(()=>submit(),0);return exam.duration*60}return x+1}),1000);return()=>clearInterval(i)}},[exam?.id,exam?.submitted,exam?.questions,exam?.duration]);const materialDocs=p.docs.filter(d=>d.role==='material'),templateDoc=p.docs.find(d=>d.role==='template'),answerDocs=p.docs.filter(d=>d.role==='answers');const correctionDoc=answerDocs.find(d=>d.id===correctionDocId)||answerDocs[0],correctionTarget=p.exams.find(e=>e.id===correctionTargetId)||p.exams[0];const topics=useMemo(()=>[...new Set(materialDocs.flatMap(d=>textParts(d.text).map(topicOf)))].slice(0,12),[materialDocs]);const createPassages=useMemo(()=>materialDocs.filter(d=>selected.includes(d.id)).flatMap(d=>textParts(d.text).map(text=>({text,name:d.name,topic:topicOf(text)}))),[materialDocs,selected]);const diffReport=useMemo(()=>difficultyReport(createPassages),[createPassages]);const learning=useMemo(()=>analyzeLearning(p.exams,p.weak,p.minutes),[p.exams,p.weak,p.minutes]);const aiConfig: AiConfig={endpoint:p.aiEndpoint||'',model:p.aiModel||'',shareConsent:aiConsent};function go(x:string){setPage(x);setCurrent(null);setShowMenu(false);setAiRequest(null);setAiConsent(false)}
async function processFile(file:File,role:'material'|'template'|'answers'){setBusy(true);setError('');setProgress(`${t.loading} ${file.name}`);let worker:any;const warningPages:number[]=[];try{let content='';let pages=1;const getOcrWorker=async()=>{if(!worker){setProgress(`${t.ocrDownload} (${p.ocrLang})`);const{createWorker}=await import('tesseract.js');worker=await createWorker(p.ocrLang||'deu',1,{logger:(m:any)=>{if(m.status==='recognizing text')setProgress(`${t.ocrWorking} ${Math.round((m.progress||0)*100)}%`)}})}return worker};if(file.type==='application/pdf'||file.name.toLowerCase().endsWith('.pdf')){const pdfjsLib=await import('pdfjs-dist');const workerAsset=await import('pdfjs-dist/build/pdf.worker.min.mjs?url');pdfjsLib.GlobalWorkerOptions.workerSrc=workerAsset.default;const pdf=await pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise;pages=pdf.numPages;for(let i=1;i<=pages;i++){setProgress(`${t.loading} ${i}/${pages}`);const pg=await pdf.getPage(i);const tx=await pg.getTextContent();let pageText=tx.items.map((x:any)=>x.str||'').join(' ').trim();if(pageText.length<35){try{const viewport=pg.getViewport({scale:2});const canvas=document.createElement('canvas');canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);const ctx=canvas.getContext('2d');if(ctx){await pg.render({canvas,canvasContext:ctx,viewport}).promise;const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,'image/png'));if(blob){const result=await(await getOcrWorker()).recognize(blob);pageText=result.data.text.trim()} }if(pageText.length<20)warningPages.push(i)}catch{warningPages.push(i)}}content+=`\n${pageText}\n`}}else if(file.type.startsWith('image/')){const result=await(await getOcrWorker()).recognize(file);content=result.data.text}else throw new Error('Nicht unterstütztes Dateiformat');content=content.replace(/\s+/g,' ').trim();const d:Doc={id:crypto.randomUUID(),name:file.name,type:file.type,text:content,pages,quality:estimateQuality(content),role,added:new Date().toISOString(),profile:role==='template'?analyzeTemplate(content):undefined,ocrWarnings:[...new Set(warningPages)]};const updated={...profileRef.current,docs:[...profileRef.current.docs,d]};profileRef.current=updated;setP(updated);try{localStorage.setItem('examvision-profile',JSON.stringify(updated))}catch(e){setError(`Browser storage unavailable: ${e instanceof Error?e.message:e}`)}await set('profile',updated).catch(e=>setError(`Local storage write failed: ${e instanceof Error?e.message:e}`));setSelected(x=>role==='material'?[...x,d.id]:x);if(content.length<45)setError(t.noText);else setProgress(`${pages} ${pages===1?'Seite':'Seiten'} · ${textParts(content).length} ${t.sourceCount}${warningPages.length?` · ${t.unreadablePages}: ${warningPages.join(', ')}`:` · ${d.quality<.5?t.needReview:'OK'}`}`)}catch(e){setError(e instanceof Error?e.message:`${t.uploadError} ${t.ocrFirstUse}`)}finally{if(worker)await worker.terminate().catch(()=>{});setBusy(false)}}
function createExam(practice=false,proposed?:Q[]){const docs=practice?materialDocs.filter(d=>!practiceTopic||d.text.toLowerCase().includes(practiceTopic.toLowerCase())):materialDocs.filter(d=>selected.includes(d.id));if(!docs.length){setError(t.noMaterial);return}const passages=docs.flatMap(d=>textParts(d.text).map(text=>({text,name:d.name,topic:topicOf(text)})));const qs=proposed?.length?proposed:buildGroundedQuestions(passages,practice?3:count,mode==='template'?templateDoc?.profile:undefined,{difficulty:level as Difficulty}) as Q[];if(!qs.length){setError(t.noText);return}const title=proposed?.length?`${t.aiReview} · ${new Date().toLocaleDateString()}`:(practice?`${t.practiceNow} · ${practiceTopic||'Alle Themen'}`:`${p.docs.find(d=>selected.includes(d.id))?.name.replace(/\.[^.]+$/,'')||t.new} · ${new Date().toLocaleDateString()}`);const e:Exam={id:crypto.randomUUID(),title,subject:topics[0]||'Lernen',created:new Date().toISOString(),mode:practice?'practice':mode,questions:qs,duration:practice?0:mins};setP(x=>({...x,exams:[e,...x.exams]}));setCurrent(e.id);setActiveQ(0);setTick(0);setPage('take');setError('');setAiQuestions([]);setAiRequest(null);setAiConsent(false)}
function answer(v:string){if(!exam)return;setP(x=>({...x,exams:x.exams.map(e=>e.id===exam.id?{...e,questions:e.questions.map((q,i)=>i===activeQ?{...q,response:v}:q)}:e)}))}function submit(){if(!exam)return;const evaluated=exam.questions.map(q=>{const result=evaluateAnswer(q.answer,q.response,q.points);return{...q,earned:result.points,confidence:result.confidence,uncertain:result.uncertain,missingConcepts:result.missingConcepts,feedback:q.response.trim().length===0?'Keine Antwort abgegeben.':result.uncertain?'Bewertung unsicher. Mit der Musterlösung vergleichen. Fehlende Begriffe: '+result.missingConcepts.join(', '):result.ratio>=.72?'Viele passende Konzepte aus der Belegstelle erkannt.':result.ratio>=.38?'Einige passende Konzepte erkannt. Fehlende Begriffe: '+result.missingConcepts.join(', '):'Wichtige Konzepte aus der Belegstelle fehlen: '+result.missingConcepts.join(', ')};});const weak=[...new Set(evaluated.filter(q=>(q.earned||0)<q.points).map(q=>q.topic))];setP(x=>({...x,weak:[...new Set([...x.weak,...weak])],minutes:x.minutes+Math.max(1,Math.round(tick/60)),exams:x.exams.map(e=>e.id===exam.id?{...e,questions:evaluated,submitted:true}:e)}));setPage('result')}
function correctUploaded(){if(!correctionDoc||!correctionTarget){setError(t.noData);return}const assigned=extractAnswerAssignments(correctionDoc.text,correctionTarget.questions.length);const uncertain=assigned.size===0;const evaluated=correctionTarget.questions.map((q,i)=>{const response=assigned.get(i)||'';const result=evaluateAnswer(q.answer,response,q.points);return{...q,response,earned:result.points,confidence:result.confidence,uncertain:uncertain||result.uncertain,missingConcepts:result.missingConcepts,feedback:uncertain?t.unassigned:response.length===0?'Keine nummerierte Antwort erkannt. Bitte manuell prüfen.':result.uncertain?'Teilweise passende Konzepte erkannt; manuell prüfen. Fehlende Begriffe: '+result.missingConcepts.join(', '):'Fehlende Begriffe: '+result.missingConcepts.join(', ')}});const weak=[...new Set(evaluated.filter(q=>(q.earned||0)<q.points).map(q=>q.topic))];setP(x=>({...x,weak:[...new Set([...x.weak,...weak])],exams:x.exams.map(e=>e.id===correctionTarget.id?{...e,questions:evaluated,submitted:true}:e)}));setCurrent(correctionTarget.id);setPage('result');if(correctionDoc.quality<.5)setError(t.needReview)}function score(e:Exam){return e.questions.reduce((a,q)=>a+(q.earned||0),0)}function total(e:Exam){return e.questions.reduce((a,q)=>a+q.points,0)}function grade(e:Exam){const pct=total(e)?score(e)/total(e)*100:0;return p.scale.findIndex(n=>pct>=n)+1||6}
function openAiRequest(kind:'questions'|'grade'){if(kind==='questions'&&!createPassages.length){setError(t.noMaterial);return}if(kind==='grade'&&(!exam||!exam.submitted)){setError(t.noExamData);return}const preview=kind==='questions'?createPassages.slice(0,4).map((passage,i)=>`[${i}] ${passage.name} · ${passage.topic}\n${passage.text.slice(0,260)}`).join('\n\n'):(exam?.questions||[]).filter(q=>q.response?.trim()).slice(0,4).map((q,i)=>`[${i}] ${q.topic} · ${q.points} ${t.points}\n${t.answer}: ${q.response}\n${t.solution}: ${q.answer}`).join('\n\n');if(!preview){setError(t.noData);return}setAiPreview(`${t.aiPreview}\n\n${preview}`);setAiRequest(kind);setAiConsent(false);setError('')}
async function performAiRequest(){if(!aiRequest)return;if(!aiConsent){setError(t.aiConsent);return}setAiBusy(true);setError('');try{validateAiConfig(aiConfig);if(aiRequest==='questions'){const sources=createPassages.map(passage=>passage.text);const result=await requestStructured<AiQuestion[]>(aiConfig,`Create ${Math.min(count,12)} exam questions. Style level: ${level}. Task kinds: ${mode==='template'?templateDoc?.profile?.taskKinds.join(', ')||'from template':'from level'}. Use only the supplied source excerpts.`,{level,profile:mode==='template'?templateDoc?.profile:undefined,sources:createPassages.map((passage,index)=>({index,name:passage.name,topic:passage.topic,text:passage.text}))},raw=>validateQuestions(raw,sources,Math.min(count,12)));setAiQuestions(result.map((question,i)=>({id:crypto.randomUUID(),prompt:question.prompt,answer:question.evidence,source:createPassages[question.sourceIndex]?.name||t.source,topic:question.topic,points:question.points,response:'',grader:'ai',feedback:t.aiReview})));setError(t.aiApplied)}else{if(!exam||!exam.submitted){setError(t.noExamData);return}const todo=exam.questions.filter(q=>q.response?.trim());const grades=new Map<string,AiGrade>();for(const q of todo){try{const result=await requestStructured<AiGrade>(aiConfig,'Grade this answer using only the supplied reference passage. Award partial points and explain missing concepts.',{topic:q.topic,maxPoints:q.points,reference:q.answer,answer:q.response},raw=>validateGrade(raw,q.points));grades.set(q.id,result)}catch{/* Keep the local grade when one request fails. */}}if(!grades.size){setError(t.aiUnavailable);return}const weakNow=[...grades].filter(([id,value])=>value.points<(exam.questions.find(q=>q.id===id)?.points||0)).map(([id])=>exam.questions.find(q=>q.id===id)?.topic||'').filter(Boolean);const updatedExams=p.exams.map(e=>e.id!==exam.id?e:{...e,questions:e.questions.map(q=>{const value=grades.get(q.id);return value?{...q,earned:value.points,confidence:value.confidence,uncertain:value.confidence<.7,missingConcepts:value.missing,feedback:`${t.aiReview} ${value.explanation}`,grader:'ai' as const}:q})});setP(x=>({...x,weak:[...new Set([...x.weak,...weakNow])],exams:updatedExams}));setError(t.aiApplied)}}catch(e){setError(`${t.aiUnavailable} ${e instanceof Error?e.message:e}`)}finally{setAiBusy(false);setAiConsent(false);setAiRequest(null);setAiPreview('')}}
async function exportPDF(e:Exam,answers=false){const[{jsPDF}]=await Promise.all([import('jspdf')]);const pdf=new jsPDF({format:'a4',unit:'mm'});const blocks=buildExamPdfBlocks(e,answers,{date:t.date,points:t.points,solution:t.solution,answer:t.answer,achieved:t.achieved});const pages=paginateBlocks(blocks);const pxPerMm=96/25.4;for(let pageIndex=0;pageIndex<pages.length;pageIndex++){if(pageIndex)pdf.addPage();for(const item of pages[pageIndex]){const y=item.y||22;if(!item.text){pdf.setDrawColor(220);pdf.line(22,y+1.5,190,y+1.5);continue}if(isRtlText(item.text)){const canvas=document.createElement('canvas');const ctx=canvas.getContext('2d');if(!ctx)continue;const fontPx=Math.max(12,Math.round(item.size*pxPerMm));ctx.font=`${fontPx}px "Segoe UI","Noto Naskh Arabic",sans-serif`;const width=Math.ceil(ctx.measureText(item.text).width)+12;canvas.width=width;canvas.height=Math.ceil(fontPx*1.7);const draw=canvas.getContext('2d')!;draw.font=ctx.font;draw.direction='rtl';draw.textAlign='right';draw.fillStyle='#111827';draw.fillText(item.text,canvas.width-4,Math.round(fontPx*1.25));pdf.addImage(canvas.toDataURL('image/png'),'PNG',item.x,y-item.size*.45,width/pxPerMm,canvas.height/pxPerMm)}else{pdf.setFont('helvetica');pdf.setFontSize(item.size);pdf.text(item.text,item.x,y)}}}const pageCount=pdf.getNumberOfPages();pdf.setFontSize(9);for(let i=1;i<=pageCount;i++){pdf.setPage(i);pdf.text(`${i} / ${pageCount}`,190,287,{align:'right'})}pdf.save(`${e.title.replace(/[^\p{L}\p{N} -]/gu,'_')}.pdf`)}
async function reportPDF(){const{jsPDF}=await import('jspdf');const pdf=new jsPDF({format:'a4',unit:'mm'});let y=22;const addLine=(text:string,size=11)=>{const lines=pdf.splitTextToSize(text,174);if(y+lines.length*5>280){pdf.addPage();y=22}pdf.setFontSize(size);pdf.text(lines,18,y);y+=lines.length*5+2};addLine(t.reportTitle,18);addLine(`${t.reportExams}: ${learning.submitted}`,12);addLine(`${t.reportMinutes}: ${learning.minutes} min`,12);addLine(`${t.avgScore}: ${learning.percent}%`,12);addLine(`${t.reportWeak}: ${learning.weakest.join(', ')||t.noWeak}`,11);addLine(t.topicResults,14);for(const topic of learning.topics.slice(0,14))addLine(`${topic.topic}: ${topic.percent}% (${topic.earned}/${topic.possible})`,10);if(learning.trend.length){addLine(t.reportTrend,14);for(const point of learning.trend)addLine(`${point.label}: ${point.percent}%`,10)}const pageCount=pdf.getNumberOfPages();pdf.setFontSize(9);for(let i=1;i<=pageCount;i++){pdf.setPage(i);pdf.text(`${i} / ${pageCount}`,190,287,{align:'right'})}pdf.save('examvision-lernfortschritt.pdf')}
function deleteAll(){if(confirm(t.deleteConfirm)){setP(empty);del('profile');localStorage.removeItem('examvision-profile');setPage('home')}}function removeDoc(id:string){setP(x=>({...x,docs:x.docs.filter(d=>d.id!==id)}));setSelected(x=>x.filter(z=>z!==id))}function navItem(key:string,Icon:any){return <button className={`navitem ${page===key?'active':''}`} onClick={()=>go(key)}><Icon size={19}/><span>{t[key]}</span></button>}
const nav=<><div className="brand"><div className="brandicon"><GraduationCap size={23}/></div><span>ExamVision <b>AI</b></span></div><div className="navlabel">{t.navLabel}</div>{navItem('home',House)}{navItem('materials',FolderOpen)}{navItem('practice',Brain)}{navItem('correction',FileCheck2)}{navItem('progress',Activity)}<div className="navspacer"/>{navItem('settings',Settings)}<div className="privacy"><ShieldCheck size={17}/><span>{t.secure}</span></div></>;
return <div className={p.lang==='ar'?'app rtl':'app'}><aside className="sidebar">{nav}</aside>{showMenu&&<div className="mobilemenu">{nav}</div>}<main className="main"><header className="topbar"><button className="iconbtn mobiletoggle" onClick={()=>setShowMenu(!showMenu)}><Menu/></button><span className="crumb">{t[page]||t.home}</span><div className="topright"><span className="localpill"><span className="greendot"/>{t.secure}</span><button className="avatar" onClick={()=>go('settings')}>EV</button></div></header>
<div className="content">{error&&<div className="alert"><span>{error}</span><button className="iconbtn" onClick={()=>setError('')}><X size={16}/></button></div>}
{page==='home'&&<><div className="hero"><div><div className="eyebrow"><Sparkles size={14}/> {t.eyebrowHome}</div><h1>{t.greeting}</h1><p>{t.sub}</p><button className="btn light" onClick={()=>{if(materialDocs.length){go('create')}else{setPage('materials');setDocRole('material');fileRef.current?.click()}}}><Plus size={18}/>{t.new}</button></div><div className="hero-art"><div className="orb"><GraduationCap size={60}/></div><span className="floatcard fc1"><FileCheck2 size={18}/> {t.sourceCount}</span><span className="floatcard fc2"><Target size={18}/> {t.practiceNow}</span></div></div><div className="statrow"><div className="stat"><span className="staticon violet"><FileText/></span><div><b>{p.docs.filter(d=>d.role==='material').length}</b><small>{t.files}</small></div></div><div className="stat"><span className="staticon cyan"><BookOpen/></span><div><b>{p.exams.length}</b><small>{t.recent}</small></div></div><div className="stat"><span className="staticon peach"><Clock3/></span><div><b>{p.minutes} {t.minutesShort}</b><small>{t.minutesStudied}</small></div></div></div><div className="quickgrid"><button className="quickcard" onClick={()=>go('create')}><span className="quickicon purple"><FilePlus2/></span><span><b>{t.new}</b><small>{t.newsub}</small></span><ChevronRight/></button><button className="quickcard" onClick={()=>go('practice')}><span className="quickicon mint"><Brain/></span><span><b>{t.practiceNow}</b><small>{t.continue}</small></span><ChevronRight/></button><button className="quickcard" onClick={()=>go('correction')}><span className="quickicon violet"><FileCheck2/></span><span><b>{t.correction}</b><small>{t.answerSheet}</small></span><ChevronRight/></button></div><section className="section"><div className="sectionhead"><div><h2>{t.recent}</h2><p>{t.recentSub}</p></div><button className="textbtn" onClick={()=>go('progress')}>{t.seeAll}<ArrowRight size={15}/></button></div>{p.exams.length===0?<div className="emptycard"><div className="emptyicon"><BookOpen/></div><b>{t.empty}</b><p>{t.emptySub}</p><button className="btn primary" onClick={()=>go('materials')}>{t.upload}</button></div>:<div className="examlist">{p.exams.slice(0,4).map(e=><button className="examrow" key={e.id} onClick={()=>{setCurrent(e.id);setPage(e.submitted?'result':'take')}}><span className="examtype"><FileCheck2/></span><span className="examname"><b>{e.title}</b><small>{new Date(e.created).toLocaleDateString()} · {e.questions.length} {t.tasks}</small></span><span className="examscore">{e.submitted?`${score(e)}/${total(e)} ${t.pointsWord}`:t.open}</span><ChevronRight size={17}/></button>)}</div>}</section><div className="notebanner"><div className="noteicon"><ShieldCheck/></div><div><b>{t.ai}</b><p>{t.aiSub}</p></div></div></>}
{page==='materials'&&<><PageHead title={t.materials} subtitle={t.intro}/><div className="uploadgrid"><button className={`uploadtile ${docRole==='material'?'selected':''}`} onClick={()=>{setDocRole('material');fileRef.current?.click()}}><span className="uploadicon violet"><Upload/></span><b>{t.material}</b><small>{t.uploadHint}</small><span className="tilecta">{t.upload} <Plus size={16}/></span></button><button className={`uploadtile ${docRole==='template'?'selected':''}`} onClick={()=>{setDocRole('template');templateRef.current?.click()}}><span className="uploadicon cyan"><FileCheck2/></span><b>{t.oldPaper}</b><small>{t.templateHint}</small><span className="tilecta">{t.upload} <Plus size={16}/></span></button><button className={`uploadtile ${docRole==='answers'?'selected':''}`} onClick={()=>{setDocRole('answers');answerRef.current?.click()}}><span className="uploadicon peach"><FileCheck2/></span><b>{t.answerSheet}</b><small>{t.answerHint}</small><span className="tilecta">{t.upload} <Plus size={16}/></span></button><input ref={fileRef} hidden type="file" accept="application/pdf,image/jpeg,image/png" multiple onChange={e=>{Array.from(e.target.files||[]).forEach(f=>processFile(f,'material'));e.currentTarget.value=''}}/><input ref={answerRef} hidden type="file" accept="application/pdf,image/jpeg,image/png" multiple onChange={e=>{Array.from(e.target.files||[]).forEach(f=>processFile(f,'answers'));e.currentTarget.value=''}}/><input ref={templateRef} hidden type="file" accept="application/pdf,image/jpeg,image/png" onChange={e=>{Array.from(e.target.files||[]).forEach(f=>processFile(f,'template'));e.currentTarget.value=''}}/></div>{busy&&<div className="processing"><span className="spinner"/>{progress}</div>}{progress&&!busy&&<div className="successline"><Check size={17}/>{progress}</div>}<div className="sectionhead docshead"><div><h2>{t.files} <span className="countpill">{p.docs.length}</span></h2><p>{t.filesHint}</p></div></div>{p.docs.length===0?<div className="emptycard"><div className="emptyicon"><FileImage/></div><b>{t.noData}</b><p>{t.uploadHint}</p></div>:<div className="doclist">{p.docs.map(d=><div className="docrow" key={d.id}><span className="docicon">{d.type==='application/pdf'?<FileText/>:<FileImage/>}</span><span className="docname"><b>{d.name}</b><small>{d.role==='material'?t.material:d.role==='template'?t.oldPaper:t.answerSheet} · {d.pages} {t.pagesShort} · {Math.round(d.quality*100)}% {t.readability}</small>{d.text.length<45&&<small className="warning">{t.noText}</small>}</span>{d.text.length>0&&<span className="passages">{textParts(d.text).length} {t.sourceCount}</span>}<button className="iconbtn danger" title={t.deleteFile} onClick={()=>removeDoc(d.id)}><Trash2 size={17}/></button></div>)}</div>}<div className="privacycard"><ShieldCheck/><div><b>{t.privacyTitle}</b><p>{t.privacyText}</p></div></div></>}
{page==='create'&&<><PageHead title={t.create} subtitle={t.intro}/><div className="formcard"><label className="fieldlabel">{t.choose}</label>{materialDocs.length===0?<div className="inlineempty"><FileText/>{t.noMaterial}<button className="textbtn" onClick={()=>go('materials')}>{t.upload}<ArrowRight size={15}/></button></div>:<div className="selectdocs">{materialDocs.map(d=><label className="selectdoc" key={d.id}><input type="checkbox" checked={selected.includes(d.id)} onChange={e=>setSelected(x=>e.target.checked?[...x,d.id]:x.filter(a=>a!==d.id))}/><FileText size={19}/><span><b>{d.name}</b><small>{textParts(d.text).length} {t.sourceCount}</small></span></label>)}</div>}<label className="fieldlabel">{t.mode}</label><div className="segmented">{[['normal',t.normal],['exam',t.exam],['template',t.template]].map(([v,n])=><button className={mode===v?'chosen':''} onClick={()=>setMode(v as string)} key={v as string}>{n}</button>)}</div>{mode==='template'&&<div className="tip"><Lightbulb size={17}/>{templateDoc?`${t.oldPaper}: ${templateDoc.name} · ${templateDoc.profile?.questionCount||1} Aufgaben · ${templateDoc.profile?.subtaskCount||0} Teilaufgaben · ${templateDoc.profile?.pointValues.join('/ ')||'Punkte unklar'} P. · Stilniveau: ${templateDoc.profile?.complexity||'unklar'} · ${templateDoc.profile?.taskKinds.join(', ')||'keine Aufgabenart erkannt'}`:`${t.oldPaper} zuerst im Materialbereich hochladen.`}</div>}<label className="fieldlabel">{t.difficulty}</label><div className="segmented">{[['easy',t.easy],['medium',t.medium],['hard',t.hard]].map(([v,n])=><button className={level===v?'chosen':''} onClick={()=>setLevel(v as string)} key={v as string}>{n}</button>)}</div><div className="diffsummary"><b>{t.difficultyReport}</b><span>{diffReport.counts.easy} {t.levelEasy} · {diffReport.counts.medium} {t.levelMedium} · {diffReport.counts.hard} {t.levelHard}</span><span>{createPassages.length} {t.sourcesAnalyzed} · {t.avgWords}: {diffReport.averageWords} · {t.avgLength}: {diffReport.averageLength}</span></div><div className="twocol"><label><span className="fieldlabel">{t.count}</span><select value={count} onChange={e=>setCount(+e.target.value)}>{[3,5,8,10,12].map(x=><option key={x}>{x}</option>)}</select></label>{mode==='exam'&&<label><span className="fieldlabel">{t.minutes}</span><input type="number" min={5} max={180} value={mins} onChange={e=>setMins(+e.target.value)}/></label>}</div><div className="groundnote"><ShieldCheck size={18}/><span><b>{t.groundTitle}</b><small>{t.groundText}</small></span></div><div className="tip"><Globe2 size={17}/>{createPassages.length?t.aiOff:t.noSelection}</div>{aiRequest==='questions'&&<div className="aipanel"><b>{t.aiPreview}</b><pre>{aiPreview}</pre><p className="muted">{t.aiHint}</p><label className="checkline"><input type="checkbox" checked={aiConsent} onChange={e=>setAiConsent(e.target.checked)}/><span>{t.aiConfirm}</span></label><div className="btnrow"><button className="btn primary" disabled={!aiConsent||aiBusy} onClick={performAiRequest}><Sparkles size={16}/>{aiBusy?t.aiSending:t.aiGenerate}</button><button className="btn secondary" onClick={()=>setAiRequest(null)}>{t.cancel}</button></div></div>}{aiQuestions.length>0&&<button className="btn secondary wide" onClick={()=>createExam(false,aiQuestions)}><Check size={17}/>{t.aiUse} ({aiQuestions.length})</button>}<button className="btn secondary wide" disabled={!createPassages.length} onClick={()=>openAiRequest('questions')}><Globe2 size={17}/>{t.aiPreviewButton}</button><button className="btn primary wide" onClick={()=>createExam()}><Sparkles size={17}/>{t.start}</button></div></>}
{page==='take'&&exam&&<><div className="sectionhead"><div><button className="textbtn" onClick={()=>go('home')}><ArrowLeft size={16}/>{t.back}</button><h1 className="pagetitle">{exam.title}</h1><p>{exam.questions.length} {t.tasks} · {exam.mode==='exam'?`${Math.floor(Math.max(0,exam.duration*60-tick)/60)}:${String(Math.max(0,exam.duration*60-tick)%60).padStart(2,'0')} ${t.remaining}`:t.noLimit}</p></div><span className="countpill">{activeQ+1} / {exam.questions.length}</span></div><div className="progressbar"><span style={{width:`${(activeQ+1)/exam.questions.length*100}%`}}/></div><div className="questioncard"><span className="eyebrow">AUFGABE {activeQ+1} · {exam.questions[activeQ]?.points} PUNKTE</span><h2>{exam.questions[activeQ]?.prompt}</h2><div className="sourcequote"><small>{t.source}: {exam.questions[activeQ]?.source}</small><p>{t.examHint}</p></div><label className="fieldlabel">{t.answer}</label><textarea rows={5} value={exam.questions[activeQ]?.response||''} onChange={e=>answer(e.target.value)} placeholder="Schreibe deine Antwort hier …"/></div><div className="questionnav">{exam.questions.map((q,i)=><button className={`qdot ${activeQ===i?'current':''} ${q.response?'filled':''}`} key={q.id} onClick={()=>setActiveQ(i)}>{i+1}</button>)}<span className="flexspace"/><button className="btn primary" onClick={()=>activeQ<exam.questions.length-1?setActiveQ(activeQ+1):submit()}>{activeQ<exam.questions.length-1?t.next:t.submit}<ArrowRight size={17}/></button></div><div className="tip"><Lightbulb size={17}/>{t.examTip}</div></>}
{page==='result'&&exam&&<><PageHead title={t.result} subtitle={exam.title}/><div className="resulthero"><div className="scorecircle"><b>{score(exam)}</b><span>{t.ofPoints} {total(exam)} {t.pointsWord}</span></div><div><div className="eyebrow">DEIN ERGEBNIS</div><h2>{t.gradeWord} {grade(exam)}</h2><p>{total(exam)?Math.round(score(exam)/total(exam)*100):0}% · {t.resultNote}</p><small className="warning">{t.needReview}: {t.aiGradeHint}</small></div></div><div className="resultactions"><button className="btn primary" onClick={()=>exportPDF(exam,false)}><ArrowDownToLine size={17}/>{t.work}</button><button className="btn secondary" onClick={()=>exportPDF(exam,true)}><FileText size={17}/>{t.withAnswers}</button><button className="btn secondary" onClick={()=>go('practice')}><Brain size={17}/>{t.continue}</button></div>{aiRequest==='grade'&&<div className="aipanel"><b>{t.aiPreview}</b><pre>{aiPreview}</pre><p className="muted">{t.aiHint}</p><label className="checkline"><input type="checkbox" checked={aiConsent} onChange={e=>setAiConsent(e.target.checked)}/><span>{t.aiConfirm}</span></label><div className="btnrow"><button className="btn primary" disabled={!aiConsent||aiBusy} onClick={performAiRequest}><Sparkles size={16}/>{aiBusy?t.aiSending:t.aiGrade}</button><button className="btn secondary" onClick={()=>setAiRequest(null)}>{t.cancel}</button></div></div>}<button className="btn secondary wide" onClick={()=>openAiRequest('grade')}><Globe2 size={17}/>{t.aiGrade}</button><div className="questionreviews">{exam.questions.map((q,i)=><article className="reviewcard" key={q.id}><div className="reviewtop"><span className="countpill">{i+1}</span><small>{q.grader==='ai'?t.aiMixed:t.aiLocal}</small><span className="reviewpoints">{q.earned??0} / {q.points} {t.pointsWord}</span></div><h3>{q.prompt}</h3><div className="reviewanswer"><small>{t.answer}</small><p>{q.response||'—'}</p></div><div className="reviewanswer reference"><small>{t.source} · {q.source}</small><p>{q.answer}</p></div><p className="feedback"><Lightbulb size={16}/>{q.feedback}</p></article>)}</div></>}
{page==='practice'&&<><PageHead title={t.practiceNow} subtitle={t.practiceEmpty}/>{topics.length===0?<div className="emptycard"><div className="emptyicon"><Brain/></div><b>{t.noMaterial}</b><p>{t.practiceEmpty}</p><button className="btn primary" onClick={()=>go('materials')}>{t.upload}</button></div>:<><div className="topicgrid">{topics.map((x,i)=><button key={x} className={`topiccard ${practiceTopic===x?'topicselected':''}`} onClick={()=>setPracticeTopic(practiceTopic===x?'':x)}><span className={`topicicon tc${i%4}`}><BookOpen/></span><span><b>{x[0]?.toUpperCase()+x.slice(1)}</b><small>{materialDocs.filter(d=>d.text.toLowerCase().includes(x)).length} Dokumente</small></span><ChevronRight size={18}/></button>)}</div><div className="tip"><ShieldCheck size={17}/>{t.intro}</div><button className="btn primary" onClick={()=>createExam(true)}><Brain size={17}/>{t.practiceNow}{practiceTopic?` · ${practiceTopic}`:''}</button></>}</>}
{page==='correction'&&<><PageHead title={t.correction} subtitle={t.correctionSub}/><div className="formcard"><label className="fieldlabel">{t.selectAnswer}</label>{answerDocs.length===0?<div className="inlineempty"><FileCheck2/>{t.noData}<button className="textbtn" onClick={()=>{go('materials');setDocRole('answers')}}>{t.upload}<ArrowRight size={15}/></button></div>:<select value={correctionDoc?.id||''} onChange={e=>setCorrectionDocId(e.target.value)}>{answerDocs.map(d=><option key={d.id} value={d.id}>{d.name} · {Math.round(d.quality*100)}%</option>)}</select>}<label className="fieldlabel">{t.selectExam}</label>{p.exams.length===0?<p className="muted">{t.createFirst}</p>:<select value={correctionTarget?.id||''} onChange={e=>setCorrectionTargetId(e.target.value)}>{p.exams.map(e=><option key={e.id} value={e.id}>{e.title} · {e.questions.length} {t.tasks}</option>)}</select>}<div className="tip"><ShieldCheck size={17}/>{t.unassigned}</div><button className="btn primary wide" disabled={!correctionDoc||!correctionTarget} onClick={correctUploaded}><FileCheck2 size={17}/>{t.correctFromFile}</button></div></>}{page==='progress'&&<><PageHead title={t.progress} subtitle={t.progressSub}/><div className="statrow progressstats"><div className="stat"><span className="staticon violet"><FileCheck2/></span><div><b>{p.exams.filter(e=>e.submitted).length}</b><small>{t.submitted}</small></div></div><div className="stat"><span className="staticon cyan"><Clock3/></span><div><b>{p.minutes} {t.minutesShort}</b><small>{t.minutesStudied}</small></div></div><div className="stat"><span className="staticon peach"><Target/></span><div><b>{p.weak.length}</b><small>{t.weak}</small></div></div></div>{learning.submitted===0?<div className="emptycard"><div className="emptyicon"><Activity/></div><b>{t.noExamData}</b><p>{t.progressSub}</p></div>:<><div className="section"><h2>{t.avgScore} · {learning.percent}%</h2><div className="trendlist">{learning.trend.map((point,i)=><div className="trendrow" key={i}><span>{point.label}</span><div className="minibar"><span style={{width:`${point.percent}%`}}/></div><b>{point.percent}%</b></div>)}</div></div><div className="section"><h2>{t.topicResults}</h2><div className="topicbars">{learning.topics.map(topic=><div className="topicbar" key={topic.topic}><span>{topic.topic}{topic.needsReview?` · ${t.needsPractice}`:''}</span><div className="minibar"><span className={topic.percent<60?'low':topic.percent>=80?'high':''} style={{width:`${topic.percent}%`}}/></div><b>{topic.percent}%</b></div>)}</div></div></>}<div className="section"><h2>{t.streak}</h2>{p.weak.length===0?<div className="emptycard"><div className="emptyicon"><Activity/></div><b>{t.noWeak}</b><p>{t.progressSub}</p></div>:<div className="topicgrid">{p.weak.map((x,i)=><button className="topiccard" key={x} onClick={()=>{setPracticeTopic(x);go('practice')}}><span className="topicicon tc3"><Target/></span><span><b>{x}</b><small>{t.weak}</small></span><ChevronRight/></button>)}</div>}</div>{p.exams.filter(e=>e.submitted).length>0&&<div className="section"><h2>{t.recent}</h2><div className="examlist">{p.exams.filter(e=>e.submitted).map(e=><div className="examrow" key={e.id}><span className="examtype"><FileCheck2/></span><span className="examname"><b>{e.title}</b><small>{new Date(e.created).toLocaleDateString()}</small></span><span className="examscore">{score(e)}/{total(e)} · Note {grade(e)}</span></div>)}</div></div>}<button className="btn secondary" onClick={reportPDF}><ArrowDownToLine size={17}/>{t.report}</button></>}
{page==='settings'&&<><PageHead title={t.settingsTitle} subtitle={t.settingsSub}/><div className="formcard"><label className="fieldlabel"><Languages size={17}/> {t.language}</label><select value={p.lang} onChange={e=>setP(x=>({...x,lang:e.target.value}))}>{[['de','Deutsch'],['en','English'],['ar','العربية'],['fr','Français'],['es','Español']].map(([v,n])=><option value={v} key={v}>{n}</option>)}</select><label className="fieldlabel">{t.documentLanguage}</label><select value={p.ocrLang} onChange={e=>setP(x=>({...x,ocrLang:e.target.value}))}>{[['deu','Deutsch'],['eng','English'],['ara','العربية'],['fra','Français'],['spa','Español']].map(([v,n])=><option value={v} key={v}>{n}</option>)}</select><label className="fieldlabel">{t.gradeScale}</label><p className="muted">{t.scaleHint}</p><div className="scalegrid">{p.scale.map((v,i)=><label key={i}><span>{t.gradeWord} {i+1}</span><div className="scaleinput"><input type="number" min={0} max={100} value={v} onChange={e=>setP(x=>({...x,scale:x.scale.map((z,j)=>j===i?+e.target.value:z)}))}/><span>%</span></div></label>)}</div><div className="settingsline"><ShieldCheck/><span><b>{t.localTitle}</b><small>{t.localText}</small></span></div><div className="settingsline"><Globe2/><span><b>{t.languageTitle}</b><small>{t.languageText}</small></span></div><div className="aisettings"><b><Globe2 size={16}/>{t.aiSettings}</b><p className="muted">{t.aiOff} {t.aiHint}</p><label className="fieldlabel">{t.aiEndpoint}</label><input type="url" placeholder="https://..." value={p.aiEndpoint||''} onChange={e=>setP(x=>({...x,aiEndpoint:e.target.value}))}/><label className="fieldlabel">{t.aiModel}</label><input type="text" value={p.aiModel||''} onChange={e=>setP(x=>({...x,aiModel:e.target.value}))}/><p className="muted">{t.aiGradeHint}</p></div><button className="btn dangerbtn" onClick={deleteAll}><Trash2 size={17}/>{t.delete}</button></div></>}
{page==='all'&&<><PageHead title={t.recent}/><div className="examlist">{p.exams.map(e=><button className="examrow" key={e.id} onClick={()=>{setCurrent(e.id);setPage(e.submitted?'result':'take')}}><span className="examtype"><FileCheck2/></span><span className="examname"><b>{e.title}</b><small>{new Date(e.created).toLocaleDateString()}</small></span><ChevronRight/></button>)}</div></>}
</div><nav className="bottomnav"><button className={page==='home'?'active':''} onClick={()=>go('home')}><House/><span>{t.home}</span></button><button className={page==='materials'?'active':''} onClick={()=>go('materials')}><FolderOpen/><span>{t.materials}</span></button><button className={page==='practice'?'active':''} onClick={()=>go('practice')}><Brain/><span>{t.practice}</span></button><button className={page==='correction'?'active':''} onClick={()=>go('correction')}><FileCheck2/><span>{t.correction}</span></button><button className={page==='progress'?'active':''} onClick={()=>go('progress')}><Activity/><span>{t.progress}</span></button></nav></main></div>}
function PageHead({title,subtitle}:{title:string,subtitle?:string}){return <div className="pagehead"><div className="eyebrow"><Sparkles size={14}/> EXAMVISION AI</div><h1>{title}</h1>{subtitle&&<p>{subtitle}</p>}</div>}
createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);
if('serviceWorker'in navigator)window.addEventListener('load',()=>{if(import.meta.env.DEV)navigator.serviceWorker.getRegistrations().then(rs=>rs.forEach(r=>r.unregister()));else navigator.serviceWorker.register('./sw.js').catch(()=>{})});
